for i in range(len(I)-3):
    for j in range(len(I[0])-3):
        if [row[j:j+4] for row in I[i:i+4]]==O: print('match',i,j)

def flips(g):
    return [g, [r[::-1] for r in g], g[::-1], [r for r in g[::-1]], [list(r) for r in zip(*g)][::-1], [list(r) for r in zip(*g[::-1])], [list(r) for r in zip(*[r[::-1] for r in g])][::-1], [list(r) for r in zip(*[r[::-1] for r in g])]]
O=G['Demo pair 1 output']
best=[]
for name,Mo in [('id',O)]+[ (f'f{i}',m) for i,m in enumerate(flips(O)) if m!=O]:
    for i in range(13):
